def test_motion_flow_uses_elapsed_sample_time_not_stride_multiplier(tmp_path,monkeypatch):
    """A known flow fixture uses fps/stride; no neural motion-accuracy claim."""
    import cv2
    import numpy as np
    from ldporto.preview_verifier import verify_preview
    video=tmp_path/'flow fixture.mp4'
    writer=cv2.VideoWriter(str(video),cv2.VideoWriter_fourcc(*'mp4v'),10,(320,180))
    assert writer.isOpened()
    try:
        for index in range(20):
            writer.write(np.full((180,320,3),150,dtype=np.uint8))
    finally:
        writer.release()
    def unit_horizontal_flow(previous,current,*args):
        """Return one pixel displacement per pair of sampled frames."""
        flow=np.zeros((*previous.shape,2),dtype=np.float32)
        flow[:,:,0]=1
        return flow
    monkeypatch.setattr(cv2,'calcOpticalFlowFarneback',unit_horizontal_flow)
    result=verify_preview(video,{'width':320,'height':180,'duration':2},[{'start':0,'end':2,'layout':'full_frame'}])['data']
    assert result['estimated_pan_flow_peak_px_per_second']==10